const state = {
  entities: [], relations: [], media: [], settings: {}, clues: [], reveals: [], knowledge: [], mapVersions: [], mapMarkers: [], workspace: [],
  editorEntity: null, editorBaseUpdatedAt: null, conversionSourceId: null, selectedId: null, selectedMapVersionId: null, markerPlacementLocationId: null, mapZoom: 100,
  mediaObjectUrls: new Map(), drafts: [], storageStatus: null, legacyAvailable: false
};

const $ = (selector) => document.querySelector(selector);
const main = $('#main');
const entryDialog = $('#entry-dialog');
const relationDialog = $('#relation-dialog');
const mediaDialog = $('#media-dialog');
const clueDialog = $('#clue-dialog');
const revealDialog = $('#reveal-dialog');
const knowledgeDialog = $('#knowledge-dialog');
const mapVersionDialog = $('#map-version-dialog');

function esc(value=''){ return String(value).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c])); }
function text(value=''){ return esc(value).replace(/\n/g,'<br>'); }
function id(){ return crypto.randomUUID?.() || `id_${Date.now()}_${Math.random().toString(16).slice(2)}`; }
function now(){ return new Date().toISOString(); }
function fmtDate(value){ if(!value) return ''; try{return new Intl.DateTimeFormat(undefined,{dateStyle:'medium'}).format(new Date(value));}catch{return value;} }
function typeLabel(type){ return ENTRY_TYPES[type]?.label || type; }
const STATUS_CLASSES={Canon:'canon',Provisional:'provisional',Concept:'concept',Contradicted:'contradicted',Shelved:'shelved',Unknown:'unknown',Open:'open',Exploring:'exploring',Answered:'answered',Inbox:'inbox',Converted:'converted'};
function statusClass(status=''){ return STATUS_CLASSES[status] || 'unknown'; }
function route(){ const raw=location.hash.replace(/^#\/?/,'')||'dashboard'; const [name,selected]=raw.split('/'); return {name,selected}; }
function setRoute(name,selected=''){ location.hash=`#/${name}${selected?`/${selected}`:''}`; }
function projectSetting(){ return state.settings.project || {name:'UnWritten.KayWorks',currentBookId:null}; }
function activeEntities(){ return state.entities.filter(e=>!e.archivedAt); }
function entityById(entityId){ return state.entities.find(e=>e.id===entityId); }
function mediaUrl(item){ if(item?.url) return item.url; if(!item?.blob) return ''; if(!state.mediaObjectUrls.has(item.id)) state.mediaObjectUrls.set(item.id,URL.createObjectURL(item.blob)); return state.mediaObjectUrls.get(item.id); }
function safeName(){ return (projectSetting().name||'world-bible').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'') || 'world-bible'; }
function pageHeader(title,description,actions=''){ return `<div class="page-header"><div><div class="eyebrow">WORLD BIBLE</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div><div class="actions">${actions}</div></div>`; }
function badge(status){ return `<span class="badge ${statusClass(status)}">${esc(status)}</span>`; }
function emptyState(title,body,button=''){ return `<div class="empty-state"><strong>${esc(title)}</strong><div>${esc(body)}</div>${button?`<div style="margin-top:14px">${button}</div>`:''}</div>`; }
function entityLink(entity,routeName){ if(!entity) return '<span class="muted">Unknown entry</span>'; const destination=entity.archivedAt?'archive':(routeName||sectionForType(entity.type)); return `<button class="inline-link" data-open-entry="${esc(entity.id)}" data-open-route="${esc(destination)}">${esc(entity.name)}</button>`; }

async function refreshState(){
  for(const url of state.mediaObjectUrls.values()) URL.revokeObjectURL(url);
  state.mediaObjectUrls.clear();
  const [entities,relations,media,settingRows,clues,reveals,knowledge,mapVersions,mapMarkers,workspace]=await Promise.all([
    getAll('entities'),getAll('relations'),getAll('media'),getAll('settings'),getAll('clues'),getAll('reveals'),getAll('knowledge'),getAll('mapVersions'),getAll('mapMarkers'),getAll('workspace')
  ]);
  Object.assign(state,{entities,relations,media,clues,reveals,knowledge,mapVersions,mapMarkers,workspace});
  state.settings=Object.fromEntries(settingRows.map(row=>[row.key,row.value]));
  $('#project-name').textContent=projectSetting().name||'UnWritten.KayWorks';
}

async function refreshDrafts(){ try{ state.drafts=(await getDrafts()).sort((a,b)=>new Date(b.savedAt)-new Date(a.savedAt)); }catch{ state.drafts=[]; } }

function toast(message){ const el=document.createElement('div'); el.className='toast'; el.textContent=message; $('#toast-region').appendChild(el); setTimeout(()=>el.remove(),3000); }
function entryListItem(entity,currentRoute='entries'){
  return `<button type="button" class="list-item entry-list-button ${entity.archivedAt?'archived-item':''}" data-open-entry="${esc(entity.id)}" data-open-route="${esc(currentRoute)}"><span><span class="list-title">${esc(entity.name||'Untitled')}</span><span class="list-meta">${esc(typeLabel(entity.type))} • edited ${esc(fmtDate(entity.updatedAt))}${entity.archivedAt?` • archived ${esc(fmtDate(entity.archivedAt))}`:''}</span></span><span class="badges">${entity.favorite?'<span class="badge">★</span>':''}${badge(entity.status)}${entity.archivedAt?'<span class="badge">Archived</span>':''}</span></button>`;
}

const COLLECTIONS={
  entries:{title:'All Lore',description:'Search and filter every structured entry in the world bible.',types:null,defaultType:'lore'},
  world:{title:'World',description:'Cosmology, ancient beings, societies, religions, creatures, organizations, artifacts, and languages.',types:['lore','deity','civilization','religion','creature','organization','artifact','language'],defaultType:'lore'},
  characters:{title:'Characters',description:'Character profiles, arcs, secrets, knowledge, beliefs, family links, and relationships.',types:['character'],defaultType:'character'},
  geography:{title:'Geography',description:'Hierarchical locations from worlds and continents down to districts, ruins, and landmarks.',types:['location'],defaultType:'location'},
  history:{title:'History',description:'Historical events and eras with sortable uncertain dates, competing interpretations, and author truth.',types:['event','era'],defaultType:'event'},
  story:{title:'Story',description:'Trilogy overview, books, chapters, and scenes kept separate from objective world lore.',types:['trilogy','book','chapter','scene'],defaultType:'book'},
  mysteries:{title:'Mysteries & Foreshadowing',description:'Track true answers, structured clues, red herrings, intended interpretations, reveals, and payoffs.',types:['mystery','foreshadowing'],defaultType:'mystery'},
  ideas:{title:'Idea Inbox',description:'Capture ideas immediately, then convert useful ones into full structured entries without copy/paste.',types:['idea'],defaultType:'idea'},
  questions:{title:'Unresolved Questions',description:'Keep author questions visible until they are answered, shelved, or developed further.',types:['question'],defaultType:'question'}
};

function renderDashboard(){
  const active=activeEntities(),project=projectSetting(),widgets=project.dashboardWidgets||['recent','questions','mysteries','ideas','warnings','compass','tasks'];
  const recent=[...active].sort((a,b)=>new Date(b.updatedAt)-new Date(a.updatedAt)).slice(0,6);
  const openQuestions=active.filter(e=>e.type==='question'&&!['Answered','Shelved'].includes(e.status)),questions=openQuestions.slice(0,5);
  const mysteries=active.filter(e=>e.type==='mystery').sort((a,b)=>Number(b.favorite)-Number(a.favorite)).slice(0,5);
  const ideas=active.filter(e=>e.type==='idea'&&e.status!=='Converted').sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)).slice(0,5);
  const books=active.filter(e=>e.type==='book').sort((a,b)=>(+a.fields?.order||999)-(+b.fields?.order||999)),currentBook=entityById(project.currentBookId)||books[0];
  const warnings=continuityWarnings({entities:state.entities,relations:state.relations,media:state.media,clues:state.clues,reveals:state.reveals,knowledge:state.knowledge,mapVersions:state.mapVersions,mapMarkers:state.mapMarkers,workspace:state.workspace}).slice(0,6);
  const tasks=state.workspace.filter(w=>w.kind==='task'&&!w.data?.done).sort((a,b)=>new Date(b.updatedAt)-new Date(a.updatedAt)).slice(0,6),series=active.find(e=>e.type==='trilogy'),compass=series?.fields||project.storyCompass||{};
  const cards=[];
  if(widgets.includes('recent')) cards.push(`<section class="card"><div class="section-title"><h2>Recently edited</h2><a href="#/entries" class="muted small">All lore →</a></div><div class="list">${recent.length?recent.map(e=>entryListItem(e,'entries')).join(''):emptyState('Nothing here yet','Create your first lore entry to start building the world.')}</div></section>`);
  if(widgets.includes('questions')) cards.push(`<section class="card"><div class="section-title"><h2>Unresolved questions</h2><a href="#/questions" class="muted small">Open →</a></div><div class="list">${questions.length?questions.map(e=>entryListItem(e,'questions')).join(''):'<div class="muted small">No open questions.</div>'}</div></section>`);
  if(widgets.includes('mysteries')) cards.push(`<section class="card"><div class="section-title"><h2>Important mysteries</h2><a href="#/mysteries" class="muted small">Open →</a></div><div class="list">${mysteries.length?mysteries.map(e=>entryListItem(e,'mysteries')).join(''):'<div class="muted small">No mysteries tracked yet.</div>'}</div></section>`);
  if(widgets.includes('ideas')) cards.push(`<section class="card"><div class="section-title"><h2>Latest ideas</h2><a href="#/ideas" class="muted small">Inbox →</a></div><div class="list">${ideas.length?ideas.map(e=>entryListItem(e,'ideas')).join(''):'<div class="muted small">Idea inbox is empty.</div>'}</div></section>`);
  if(widgets.includes('warnings')) cards.push(`<section class="card"><div class="section-title"><h2>Continuity warnings</h2><a href="#/continuity" class="muted small">Inspect →</a></div><div class="tracking-list">${warnings.length?warnings.map(w=>`<div class="tracking-row"><div><strong>${esc(w.message)}</strong><div class="list-meta">${esc(w.code||'continuity')}</div></div></div>`).join(''):'<div class="muted small">No deterministic warnings found.</div>'}</div></section>`);
  if(widgets.includes('compass')) cards.push(`<section class="card"><div class="section-title"><h2>Story Compass</h2><a href="#/plot-grid" class="muted small">Edit →</a></div>${compass.startingState||compass.beginning||compass.endGoal||compass.intendedEnding?`<div class="tracking-list"><div class="tracking-row"><div><div class="muted small">Beginning</div><strong>${esc(compass.startingState||compass.beginning||'Not fixed yet')}</strong></div></div><div class="tracking-row"><div><div class="muted small">End goal / central truth</div><strong>${esc(compass.endGoal||compass.centralPrizeTruth||'Not fixed yet')}</strong></div></div><div class="tracking-row"><div><div class="muted small">Ending</div><strong>${esc(compass.intendedEnding||'Not fixed yet')}</strong></div></div></div>`:'<div class="muted small">Optional anchors are empty. Add them only if you already know where the story begins or ends.</div>'}</section>`);
  if(widgets.includes('tasks')) cards.push(`<section class="card"><div class="section-title"><h2>Worldbuilding tasks</h2><a href="#/workbench" class="muted small">Workbench →</a></div><div class="tracking-list">${tasks.length?tasks.map(t=>`<div class="tracking-row"><div><strong>${esc(t.title)}</strong><div class="list-meta">${esc(t.data?.due||'No milestone')}</div></div></div>`).join(''):'<div class="muted small">No open tasks.</div>'}</div></section>`);
  main.innerHTML=pageHeader(project.name||'UnWritten.KayWorks','Your private control center for canon, continuity, story structure, maps, mysteries, and author work.','<button class="button primary" data-new-entry="lore">+ New entry</button>')+`
    <div class="grid stats"><div class="card"><div class="muted small">Active entries</div><div class="stat-value">${active.length}</div></div><div class="card"><div class="muted small">Canon</div><div class="stat-value">${active.filter(e=>e.status==='Canon').length}</div></div><div class="card"><div class="muted small">Open questions</div><div class="stat-value">${openQuestions.length}</div></div><div class="card"><div class="muted small">Continuity warnings</div><div class="stat-value">${warnings.length}</div></div></div>
    ${state.drafts.length?`<section class="card section"><div class="section-title"><div><h2>Unsaved drafts on this device</h2><div class="muted small">Drafts are temporary recovery copies. Saved canon lives in D1.</div></div></div><div class="list">${state.drafts.map(d=>`<div class="tracking-row"><div><div class="list-title">${esc(d.entity?.name||'Untitled draft')}</div><div class="list-meta">${esc(typeLabel(d.entity?.type||'lore'))} • cached ${esc(fmtDate(d.savedAt))}</div></div><div class="actions"><button class="button ghost" data-recover-draft="${esc(d.id)}">Recover</button><button class="icon-btn" data-discard-draft="${esc(d.id)}" aria-label="Discard draft">×</button></div></div>`).join('')}</div></section>`:''}
    <div class="grid two section"><section class="card"><div class="section-title"><h2>Quick capture</h2><span class="muted small">Idea inbox</span></div><form id="quick-idea-form" class="quick-capture"><input id="quick-idea" placeholder="City built inside the fossilized remains of…" required /><button class="button primary" type="submit">Save idea</button></form></section><section class="card"><div class="section-title"><h2>Current book</h2><a href="#/story" class="muted small">Story →</a></div>${currentBook?entryListItem(currentBook,'story'):emptyState('No book selected','Create a Book entry, then select it in Settings.')}</section></div>
    <section class="card section"><div class="section-title"><h2>Working views</h2><a href="#/workbench" class="muted small">Customize dashboard →</a></div><div class="actions"><a class="button" href="#/continuity">Continuity</a><a class="button" href="#/plot-grid">Plot Grid</a><a class="button" href="#/timeline">Timeline</a><a class="button" href="#/maps">Maps</a><a class="button" href="#/world-tools">World Tools</a><a class="button" href="#/reader-preview">Reader Preview</a></div></section>
    <div class="dashboard-widget-grid section">${cards.join('')}</div>`;
}

function renderCollection(routeName,selectedId){
  const cfg=COLLECTIONS[routeName]||COLLECTIONS.entries;
  const base=activeEntities(); const pool=cfg.types?base.filter(e=>cfg.types.includes(e.type)):base;
  const tags=uniqueTags(pool); const selected=state.entities.find(e=>e.id===selectedId&&!e.archivedAt)||pool[0]||null; state.selectedId=selected?.id||null;
  const typeOptions=cfg.types&&cfg.types.length===1?'':`<select id="collection-type"><option value="">All types</option>${(cfg.types||Object.keys(ENTRY_TYPES)).map(t=>`<option value="${esc(t)}">${esc(typeLabel(t))}</option>`).join('')}</select>`;
  const statusSet=[...new Set(pool.map(e=>e.status))].sort();
  const extraStory=routeName==='story'?renderTrilogyOverview():'';
  main.innerHTML=pageHeader(cfg.title,cfg.description,`<button class="button primary" data-new-entry="${esc(cfg.defaultType)}">+ New ${esc(typeLabel(cfg.defaultType))}</button>`)+extraStory+`
    <div class="entry-layout ${extraStory?'section':''}"><section class="card list-panel"><div class="filter-row"><input id="collection-search" type="search" placeholder="Filter this section…" />${typeOptions}<select id="collection-status"><option value="">All statuses</option>${statusSet.map(s=>`<option>${esc(s)}</option>`).join('')}</select><select id="collection-tag"><option value="">All tags</option>${tags.map(t=>`<option>${esc(t)}</option>`).join('')}</select></div><div id="collection-list" class="list"></div></section><section class="card detail-panel" id="detail-panel">${selected?renderEntryDetail(selected,routeName):emptyState('No entries yet','Create the first entry in this section to begin.')}</section></div>`;
  const update=()=>{ const q=$('#collection-search')?.value||'',type=$('#collection-type')?.value||'',status=$('#collection-status')?.value||'',tag=$('#collection-tag')?.value||''; const results=searchEntities(pool,q,{type:type||null,status:status||null,tag:tag||null}); $('#collection-list').innerHTML=results.length?results.map(e=>entryListItem(e,routeName)).join(''):emptyState('No matches','Try a different search or filter.'); };
  ['#collection-search','#collection-type','#collection-status','#collection-tag'].forEach(sel=>$(sel)?.addEventListener('input',update)); update();
}

function renderTrilogyOverview(){
  const trilogy=activeEntities().find(e=>e.type==='trilogy');
  if(!trilogy) return `<section class="card"><div class="section-title"><div><h2>Series Overview</h2><div class="muted small">One optional high-level record for the whole series, including the fixed anchors you already know.</div></div><button class="button" data-new-entry="trilogy">Create overview</button></div></section>`;
  return `<section class="card trilogy-overview"><div class="section-title"><div><div class="eyebrow">SERIES OVERVIEW</div><h2>${esc(trilogy.name)}</h2></div><button class="button" data-open-entry="${esc(trilogy.id)}" data-open-route="story">Open overview</button></div><div class="muted">${esc(trilogy.summary||trilogy.fields?.centralPremise||'No premise written yet.')}</div></section>`;
}

function displayFieldValue(field,value,routeName){
  if(field.type==='entity'){ const target=entityById(value); return target?entityLink(target,routeName):`<span class="muted">Missing linked entry (${esc(value)})</span>`; }
  return `<div class="prose">${text(value)}</div>`;
}

function hierarchyBreadcrumb(entity){
  const parts=[]; let current=entity; let guard=0;
  while(current&&guard++<12){ parts.unshift(current); let parentId=null; if(current.type==='location') parentId=current.fields?.parentLocationId; if(current.type==='chapter') parentId=current.fields?.parentBookId; if(current.type==='scene') parentId=current.fields?.parentChapterId; current=parentId?entityById(parentId):null; }
  return parts.length>1?`<div class="breadcrumbs">${parts.map((p,i)=>`${i?'› ':''}<button class="inline-link" data-open-entry="${esc(p.id)}" data-open-route="${esc(sectionForType(p.type))}">${esc(p.name)}</button>`).join(' ')}</div>`:'';
}

function renderEntryDetail(entity,routeName='entries'){
  const def=ENTRY_TYPES[entity.type]; const rels=relationsFor(entity.id,state.relations);
  const relatedHtml=rels.map(rel=>{ const other=entityById(otherEntityId(rel,entity.id)); if(!other) return ''; const dir=relationDirection(rel,entity.id)==='outgoing'?'→':'←'; return `<div class="list-item related-row"><button type="button" class="related-open" data-open-entry="${esc(other.id)}" data-open-route="${esc(other.archivedAt?'archive':sectionForType(other.type))}"><span class="list-title">${esc(other.name)}</span><span class="list-meta">${dir} ${esc(rel.type.replaceAll('_',' '))}${rel.eraId?` • ${esc(entityById(rel.eraId)?.name||'Era')}`:''}${rel.activeFrom||rel.activeTo?` • ${esc([rel.activeFrom||'…',rel.activeTo||'…'].join(' → '))}`:''}${rel.note?` • ${esc(rel.note)}`:''}</span></button><button class="icon-btn" data-delete-relation="${esc(rel.id)}" aria-label="Remove link">×</button></div>`; }).join('');
  const linkedMedia=state.media.filter(m=>(m.entityIds||[]).includes(entity.id));
  const detailFields=(def?.fields||[]).filter(f=>!f.knowledge&&entity.fields?.[f.key]!==undefined&&String(entity.fields[f.key]).trim()!=='');
  const knowledgeFields=(def?.fields||[]).filter(f=>f.knowledge&&entity.fields?.[f.key]&&String(entity.fields[f.key]).trim());
  const specialActions=[entity.type==='idea'&&entity.status!=='Converted'?`<button class="button primary" data-convert-idea="${esc(entity.id)}">Convert to entry</button>`:'',entity.type==='mystery'?`<button class="button" data-add-clue="${esc(entity.id)}">+ Clue</button><button class="button" data-add-reveal="${esc(entity.id)}">+ Reveal</button>`:'',entity.archivedAt?`<button class="button" data-unarchive-entry="${esc(entity.id)}">Restore</button>`:''].join('');
  return `${entity.archivedAt?'<div class="archive-banner">This entry is archived. It remains in backups and can be restored or permanently deleted.</div>':''}${hierarchyBreadcrumb(entity)}
    <div class="detail-head"><div><div class="eyebrow">${esc(def?.group||'ENTRY')} • ${esc(def?.label||entity.type)}</div><h2>${esc(entity.name)}</h2><div class="badges">${badge(entity.status)}${(entity.tags||[]).map(t=>`<span class="badge">#${esc(t)}</span>`).join('')}</div></div><div class="actions">${specialActions}<button class="button ghost" data-toggle-favorite="${esc(entity.id)}">${entity.favorite?'★ Favorited':'☆ Favorite'}</button><button class="button" data-edit-entry="${esc(entity.id)}">Edit</button></div></div>
    ${entity.summary?`<section class="detail-section"><h3>Summary</h3><div class="prose">${text(entity.summary)}</div></section>`:''}
    ${knowledgeFields.length?`<section class="detail-section"><h3>Knowledge layers</h3><div class="knowledge-grid">${knowledgeFields.map(f=>`<div class="knowledge-card"><h4>${esc(f.label)}</h4><div class="prose">${text(entity.fields[f.key])}</div></div>`).join('')}</div></section>`:''}
    ${detailFields.map(f=>`<section class="detail-section"><h3>${esc(f.label)}</h3>${displayFieldValue(f,entity.fields[f.key],routeName)}</section>`).join('')}
    ${entity.type==='mystery'?renderMysteryTracking(entity):''}
    ${entity.type==='character'?renderCharacterKnowledgeSummary(entity):''}
    ${entity.type==='location'?renderLocationMapLinks(entity):''}
    ${entity.notes?`<section class="detail-section"><h3>Author Notes</h3><div class="prose">${text(entity.notes)}</div></section>`:''}
    ${v3().renderEntryEnhancements(entity)}
    <section class="detail-section"><div class="section-title"><h3>Related entries</h3><button class="button ghost" data-add-relation="${esc(entity.id)}">+ Link entry</button></div><div class="list">${relatedHtml||'<div class="muted small">No structured links yet.</div>'}</div></section>
    <section class="detail-section"><div class="section-title"><h3>Images & media</h3><button class="button ghost" data-add-media="${esc(entity.id)}">+ Attach media</button></div>${renderMiniMedia(linkedMedia)}</section>
    <section class="detail-section"><div class="muted small">Created ${esc(fmtDate(entity.createdAt))} • Last edited ${esc(fmtDate(entity.updatedAt))}</div></section>`;
}

function renderMysteryTracking(entity){
  const clues=state.clues.filter(c=>c.mysteryId===entity.id||(c.mysteryIds||[]).includes(entity.id)).sort((a,b)=>compareStoryRefs(a.storyEntityId,b.storyEntityId,state.entities)||(Number(a.order)||999)-(Number(b.order)||999));
  const reveals=state.reveals.filter(r=>r.mysteryId===entity.id);
  const clueHtml=clues.map(c=>`<div class="tracking-row"><div><div class="list-title">${esc(c.label||c.kind||'Clue')}</div><div class="list-meta">${esc(c.kind||'Clue')}${c.storyEntityId?` • ${esc(storyPath(entityById(c.storyEntityId),state.entities))}`:''}${c.visibility?` • ${esc(c.visibility)}`:''}</div><div class="small" style="margin-top:6px">${esc(c.description||'')}</div></div><button class="icon-btn" data-delete-clue="${esc(c.id)}" aria-label="Delete clue">×</button></div>`).join('');
  const revealHtml=reveals.map(r=>`<div class="tracking-row"><div><div class="list-title">${esc(r.title)}</div><div class="list-meta">${esc(revealStoryPath(r)||'Unscheduled')}</div><div class="small" style="margin-top:6px">${esc(r.summary||'')}</div></div><button class="icon-btn" data-delete-reveal="${esc(r.id)}" aria-label="Delete reveal">×</button></div>`).join('');
  return `<section class="detail-section"><div class="section-title"><h3>Structured clue path</h3><button class="button ghost" data-add-clue="${esc(entity.id)}">+ Add clue</button></div><div class="tracking-list">${clueHtml||'<div class="muted small">No structured clues yet.</div>'}</div></section><section class="detail-section"><div class="section-title"><h3>Reader reveals</h3><button class="button ghost" data-add-reveal="${esc(entity.id)}">+ Add reveal</button></div><div class="tracking-list">${revealHtml||'<div class="muted small">No reader reveal records yet.</div>'}</div></section>`;
}

function renderCharacterKnowledgeSummary(character){
  const rows=state.knowledge.filter(k=>k.knowerKind==='character'&&k.knowerEntityId===character.id);
  if(!rows.length) return `<section class="detail-section"><div class="section-title"><h3>Structured knowledge</h3><button class="button ghost" data-add-knowledge-for="${esc(character.id)}">+ Knowledge record</button></div><div class="muted small">No structured knowledge records yet.</div></section>`;
  return `<section class="detail-section"><div class="section-title"><h3>Structured knowledge</h3><button class="button ghost" data-add-knowledge-for="${esc(character.id)}">+ Knowledge record</button></div><div class="tracking-list">${rows.map(k=>`<div class="tracking-row"><div><div class="list-title">${esc(entityById(k.subjectEntityId)?.name||'Missing subject')}</div><div class="list-meta">${esc(k.state)}${k.storyEntityId?` • by ${esc(storyPath(entityById(k.storyEntityId),state.entities))}`:''}</div><div class="small">${esc(k.belief||'')}</div></div></div>`).join('')}</div></section>`;
}


function renderLocationMapLinks(location){
  const maps=mapsForLocation(location.id);
  return `<section class="detail-section"><div class="section-title"><div><h3>Maps</h3><div class="muted small">Visual maps whose geographic scope is this location.</div></div><button class="button ghost" data-new-map-for="${esc(location.id)}">+ Map this location</button></div>${maps.length?`<div class="atlas-grid">${maps.map(m=>atlasMapItem(m,'')).join('')}</div>`:'<div class="muted small">No visual map for this location yet.</div>'}</section>`;
}

function createMapForLocation(locationId){
  const location=entityById(locationId); if(!location) return;
  const map=createEmptyEntity('map'); map.name=`${location.name} Map`; map.summary=`Visual map of ${location.name}.`;
  const parentMap=preferredMapForLocation(location.fields?.parentLocationId||'');
  const kindMap={World:'World',Continent:'Continent',Country:'Country',City:'City'};
  map.fields={scopeLocationId:location.id,parentMapId:parentMap?.id||'',mapKind:kindMap[location.fields?.locationKind]||'Other',coverage:location.name};
  openEntryEditor('map',null,map);
}

function renderMiniMedia(media){ if(!media.length) return '<div class="muted small">No media attached.</div>'; return `<div class="media-grid">${media.map(item=>{const src=mediaUrl(item);return `<div class="media-card">${src?`<img src="${src}" alt="${esc(item.title||item.name||'Attached image')}" />`:''}<div class="media-card-body"><strong>${esc(item.title||item.name)}</strong><div class="muted small">${(item.tags||[]).map(t=>`#${esc(t)}`).join(' ')}</div></div></div>`;}).join('')}</div>`; }

function renderTimeline(){
  const events=activeEntities().filter(e=>e.type==='event'),eras=activeEntities().filter(e=>e.type==='era').sort((a,b)=>a.name.localeCompare(b.name));
  const locations=activeEntities().filter(e=>e.type==='location').sort((a,b)=>a.name.localeCompare(b.name));
  const actors=activeEntities().filter(e=>['character','organization','civilization','religion'].includes(e.type)).sort((a,b)=>a.name.localeCompare(b.name));
  const books=activeEntities().filter(e=>e.type==='book').sort((a,b)=>(Number(a.fields?.order)||999)-(Number(b.fields?.order)||999));
  const relatedTo=(eventId,targetId)=>state.relations.some(r=>(r.fromId===eventId&&r.toId===targetId)||(r.toId===eventId&&r.fromId===targetId));
  main.innerHTML=pageHeader('Timelines','Use the same Event records as world history, character history, wars, kingdoms, and book-planning views. Uncertain wording stays intact.','<button class="button primary" data-new-entry="event">+ Historical Event</button>')+`<section class="card"><div class="filter-row timeline-filters"><select id="timeline-view"><option value="world">World History</option><option value="character">Character / Faction</option><option value="location">Location / Kingdom</option><option value="book">Book Story Timeline</option></select><select id="timeline-focus"><option value="">All / choose focus…</option></select><select id="timeline-era"><option value="">All eras</option>${eras.map(e=>`<option value="${esc(e.id)}">${esc(e.name)}</option>`).join('')}</select><select id="timeline-certainty"><option value="">All certainty levels</option>${['Exact','Approximate','Range','Traditional','Disputed','Unknown'].map(x=>`<option>${x}</option>`).join('')}</select><input id="timeline-search" type="search" placeholder="Search events, tags, dates…"/></div><div class="muted small section">Use Display Date for prose like “circa 400–430” or “before the Second War”; sortable values remain optional and only control ordering.</div><div id="timeline-results"></div></section>`;
  const fillFocus=()=>{const view=$('#timeline-view').value,focus=$('#timeline-focus');let pool=[];if(view==='character')pool=actors;if(view==='location')pool=locations;if(view==='book')pool=books;focus.innerHTML='<option value="">All / choose focus…</option>'+pool.map(e=>`<option value="${esc(e.id)}">${esc(e.name)}</option>`).join('');};
  const update=()=>{ const view=$('#timeline-view').value,focusId=$('#timeline-focus').value,eraId=$('#timeline-era').value,certainty=$('#timeline-certainty').value,q=$('#timeline-search').value.trim().toLowerCase(); let filtered=events.filter(e=>!eraId||e.fields?.eraId===eraId).filter(e=>!certainty||e.fields?.dateUncertainty===certainty); if(focusId){ if(view==='location')filtered=filtered.filter(e=>e.fields?.locationId===focusId||relatedTo(e.id,focusId)); else if(view==='book')filtered=filtered.filter(e=>relatedTo(e.id,focusId)||(e.tags||[]).some(t=>t.toLowerCase()===`book:${focusId.toLowerCase()}`||t.toLowerCase()===entityById(focusId)?.name?.toLowerCase())); else if(view==='character')filtered=filtered.filter(e=>relatedTo(e.id,focusId)); } if(q)filtered=filtered.filter(e=>[e.name,e.summary,e.fields?.dateText,e.fields?.locationText,...(e.tags||[])].join(' ').toLowerCase().includes(q)); filtered.sort(compareTimelineEvents); const groups=new Map(); for(const event of filtered){ const key=event.fields?.eraId||'__unassigned'; (groups.get(key)||groups.set(key,[]).get(key)).push(event); } $('#timeline-results').innerHTML=filtered.length?[...groups.entries()].map(([key,items])=>`<section class="era-band"><div class="era-band-title">${esc(key==='__unassigned'?'Unassigned era':entityById(key)?.name||'Missing era')}</div><div class="timeline">${items.map(e=>`<div class="timeline-item"><button type="button" class="list-item entry-list-button" data-open-entry="${esc(e.id)}" data-open-route="history"><span><span class="list-title">${esc(e.name)}</span><span class="list-meta">${esc(eventRangeLabel(e))}${e.fields?.dateUncertainty?` • ${esc(e.fields.dateUncertainty)}`:''}${e.fields?.locationId?` • ${esc(entityById(e.fields.locationId)?.name||'Location')}`:''}</span>${e.summary?`<span class="small timeline-summary">${esc(e.summary)}</span>`:''}</span>${badge(e.status)}</button></div>`).join('')}</div></section>`).join(''):emptyState('No events match','Add historical events or change the filters.'); };
  $('#timeline-view').addEventListener('input',()=>{fillFocus();update();}); ['#timeline-focus','#timeline-era','#timeline-certainty','#timeline-search'].forEach(sel=>$(sel)?.addEventListener('input',update)); fillFocus(); update();
}

function mapVersionForMap(mapId){ const versions=state.mapVersions.filter(v=>v.mapId===mapId).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)); return versions.find(v=>v.id===state.selectedMapVersionId)||versions[0]||null; }
function mapScope(map){ return map?.fields?.scopeLocationId ? entityById(map.fields.scopeLocationId) : null; }
function mapsForLocation(locationId){ return activeEntities().filter(e=>e.type==='map'&&e.fields?.scopeLocationId===locationId); }
function preferredMapForLocation(locationId,parentMapId=''){ const matches=mapsForLocation(locationId).filter(m=>m.id!==parentMapId); return matches.find(m=>m.fields?.parentMapId===parentMapId)||matches[0]||null; }
function mapParent(map){ return map?.fields?.parentMapId ? entityById(map.fields.parentMapId) : null; }
function mapBreadcrumb(map){ const parts=[]; let current=map,guard=0; while(current&&guard++<12){ parts.unshift(current); current=mapParent(current); } return parts.length>1?`<div class="breadcrumbs atlas-breadcrumbs">${parts.map((m,i)=>`${i?'› ':''}<button class="inline-link" data-open-map="${esc(m.id)}">${esc(m.name)}</button>`).join(' ')}</div>`:''; }
function mapThumb(map){ const version=mapVersionForMap(map.id); const media=version?state.media.find(m=>m.id===version.mediaId):null; const src=mediaUrl(media); return src?`<img src="${src}" alt="" />`:'<span class="map-thumb-empty">▧</span>'; }
function atlasMapItem(map,selectedId){ const scope=mapScope(map); const versions=state.mapVersions.filter(v=>v.mapId===map.id).length; return `<button type="button" class="atlas-map-item ${map.id===selectedId?'active':''}" data-open-map="${esc(map.id)}"><span class="atlas-map-thumb">${mapThumb(map)}</span><span class="atlas-map-copy"><strong>${esc(map.name)}</strong><span>${esc(scope?.name||map.fields?.coverage||'Unscoped map')} • ${versions} image${versions===1?'':'s'}</span></span></button>`; }

function markerCategoryIcon(marker){
  if(marker.icon) return marker.icon;
  return ({City:'◆',Settlement:'●',Ruin:'⌂',Landmark:'✦',Battle:'⚔',Religious:'✧',Capital:'♛',Geography:'▲',Story:'★',Other:'•'})[marker.category]||'•';
}
function clusterMapMarkers(markers){
  if(state.mapZoom>50) return markers.map(marker=>({markers:[marker],x:Number(marker.x),y:Number(marker.y)}));
  const cells=new Map();
  for(const marker of markers){ const key=`${Math.round(Number(marker.x)/12)}:${Math.round(Number(marker.y)/12)}`; if(!cells.has(key))cells.set(key,[]); cells.get(key).push(marker); }
  return [...cells.values()].map(group=>({markers:group,x:group.reduce((n,m)=>n+Number(m.x),0)/group.length,y:group.reduce((n,m)=>n+Number(m.y),0)/group.length}));
}
function renderMaps(selectedMapId){
  const maps=activeEntities().filter(e=>e.type==='map').sort((a,b)=>a.name.localeCompare(b.name));
  const selected=entityById(selectedMapId)?.type==='map'?entityById(selectedMapId):maps[0]||null;
  const locations=activeEntities().filter(e=>e.type==='location').sort((a,b)=>a.name.localeCompare(b.name));
  const characters=activeEntities().filter(e=>e.type==='character').sort((a,b)=>a.name.localeCompare(b.name));
  const factions=activeEntities().filter(e=>['organization','civilization','religion'].includes(e.type)).sort((a,b)=>a.name.localeCompare(b.name));
  const books=activeEntities().filter(e=>e.type==='book').sort((a,b)=>(Number(a.fields?.order)||999)-(Number(b.fields?.order)||999));
  const legacy=state.media.filter(m=>(m.tags||[]).some(t=>t.toLowerCase()==='map')&&!state.mapVersions.some(v=>v.mediaId===m.id));
  const version=selected?mapVersionForMap(selected.id):null;
  const versions=selected?state.mapVersions.filter(v=>v.mapId===selected.id).sort((a,b)=>String(a.effectiveDate||a.createdAt).localeCompare(String(b.effectiveDate||b.createdAt))):[];
  const media=version?state.media.find(m=>m.id===version.mediaId):null;
  const markers=version?state.mapMarkers.filter(m=>m.mapVersionId===version.id):[];
  const layers=version?state.workspace.filter(w=>w.kind==='mapLayer'&&w.data?.mapVersionId===version.id):[];
  const routes=version?state.workspace.filter(w=>w.kind==='mapRoute'&&w.data?.mapVersionId===version.id):[];
  const scope=mapScope(selected), childMaps=selected?maps.filter(m=>m.fields?.parentMapId===selected.id):[];
  const rootMaps=maps.filter(m=>!m.fields?.parentMapId||!entityById(m.fields.parentMapId)); const listOrder=[...rootMaps,...maps.filter(m=>!rootMaps.includes(m))];
  const categoryOptions=['City','Settlement','Ruin','Landmark','Battle','Religious','Capital','Geography','Story','Other'];
  const visibleLayers=new Set(layers.filter(l=>l.data?.visible!==false).map(l=>l.id));
  const layerHtml=layers.map(layer=>{const layerMedia=state.media.find(m=>m.id===layer.data?.mediaId),src=mediaUrl(layerMedia);return src?`<img class="map-layer-image" data-map-layer-image="${esc(layer.id)}" src="${src}" alt="${esc(layer.title||'Map layer')}" style="opacity:${Math.max(0,Math.min(1,Number(layer.data?.opacity??.55)))};${layer.data?.visible===false?'display:none;':''}"/>`:'';}).join('');
  const routeHtml=routes.map(routeItem=>{const points=(routeItem.data?.markerIds||[]).map(mid=>markers.find(m=>m.id===mid)).filter(Boolean);if(points.length<2)return '';const pts=points.map(m=>`${Number(m.x)},${Number(m.y)}`).join(' ');return `<polyline class="map-route-line" points="${pts}" vector-effect="non-scaling-stroke"><title>${esc(routeItem.title||'Route')}</title></polyline>`;}).join('');
  const groups=clusterMapMarkers(markers);
  const markerHtml=groups.map(group=>{if(group.markers.length>1)return `<button type="button" class="map-marker-cluster" style="left:${group.x}%;top:${group.y}%" data-cluster-zoom="1" title="Zoom in to ${group.markers.length} nearby markers">${group.markers.length}</button>`;const m=group.markers[0],location=entityById(m.locationId),drill=preferredMapForLocation(m.locationId,selected?.id),custom=state.media.find(x=>x.id===m.customMediaId),customSrc=mediaUrl(custom),label=m.label||location?.name||'Location';return `<button type="button" draggable="true" class="map-marker ${drill?'has-drilldown':''}" data-marker-id="${esc(m.id)}" data-marker-name="${esc(label.toLowerCase())}" data-marker-category="${esc(m.category||'Other')}" data-marker-tags="${esc((m.tags||[]).join(' ').toLowerCase())}" data-marker-layer="${esc(m.layerId||'')}" data-marker-active="${esc(`${m.activeFrom||''} ${m.activeTo||''}`.toLowerCase())}" data-marker-faction="${esc(m.factionId||'')}" data-marker-books="${esc((m.bookIds||[]).join(' '))}" data-marker-relevance="${esc((m.storyRelevance||'').toLowerCase())}" data-marker-enabled="${m.active===false?'false':'true'}" style="left:${Number(m.x)}%;top:${Number(m.y)}%" ${drill?`data-open-map="${esc(drill.id)}"`:`data-open-entry="${esc(m.locationId)}" data-open-route="geography"`} title="${esc(drill?`Open ${drill.name}`:`Open ${label}. Drag to reposition.`)}">${customSrc?`<img class="marker-custom-image" src="${customSrc}" alt=""/>`:`<span class="marker-symbol">${esc(markerCategoryIcon(m))}</span>`}<b>${esc(label)}${drill?' ↘':''}</b></button>`;}).join('');

  main.innerHTML=pageHeader('Maps','Navigate layered, historical maps with searchable markers, routes, and drill-down geography.','<button class="button primary" data-new-entry="map">+ New map record</button>')+`
    <div class="map-layout"><section class="card list-panel atlas-panel"><div class="section-title"><div><h2>Atlas</h2><div class="muted small">World → continent → kingdom → city, or any hierarchy you choose.</div></div></div><div class="atlas-list">${listOrder.length?listOrder.map(m=>atlasMapItem(m,selected?.id)).join(''):emptyState('No maps yet','Create a map record, choose its geographic scope, then upload an image.')}</div>${legacy.length?`<div class="form-section"><h3>Legacy #map media</h3><div class="muted small">${legacy.length} older map image${legacy.length===1?' is':'s are'} still safe in Media.</div></div>`:''}</section>
    <section class="card map-workspace">${selected?`${mapBreadcrumb(selected)}<div class="section-title"><div><div class="eyebrow">${esc(selected.fields?.mapKind||'MAP')} ${scope?`• ${esc(scope.fields?.locationKind||'Location')}`:''}</div><h2>${esc(selected.name)}</h2><div class="muted small">${scope?`Covers ${esc(scope.name)}`:esc(selected.fields?.coverage||'No geographic scope selected yet.')}</div></div><div class="actions"><button class="button" data-edit-entry="${esc(selected.id)}">Edit map</button><button class="button primary" data-add-map-version="${esc(selected.id)}">Upload map image</button></div></div>
      ${versions.length?`<div class="version-strip" aria-label="Historical map versions">${versions.map(v=>`<span class="version-chip-wrap"><button type="button" class="version-chip ${v.id===version?.id?'active':''}" data-map-version="${esc(v.id)}">${esc(v.label||v.variant||'Version')}<span>${esc(v.effectiveDate||fmtDate(v.createdAt))}</span></button><button type="button" class="version-delete" data-delete-map-version="${esc(v.id)}" aria-label="Delete ${esc(v.label||'map version')}">×</button></span>`).join('')}</div>`:''}
      ${media?`<div class="map-toolbar"><label>Place a location pin<select id="marker-location"><option value="">Choose a location…</option>${locations.map(l=>`<option value="${esc(l.id)}">${esc(l.name)}${mapsForLocation(l.id).length?' • has map':''}</option>`).join('')}</select></label><label>Category<select id="marker-category">${categoryOptions.map(c=>`<option>${c}</option>`).join('')}</select></label><label>Icon<input id="marker-icon" maxlength="4" placeholder="optional symbol"/></label><button class="button" id="arm-marker">Place pin</button><div class="map-zoom-controls" aria-label="Map zoom"><button class="button ghost" type="button" data-zoom-map="out">−</button><button class="button ghost" type="button" data-zoom-map="fit">Fit</button><span id="map-zoom-label" class="muted small">${state.mapZoom}%</span><button class="button ghost" type="button" data-zoom-map="in">+</button></div></div><div class="map-marker-options"><label>Label<input id="marker-label" placeholder="optional map label"/></label><label>Tags<input id="marker-tags" placeholder="capital, book-one…"/></label><label>Active from<input id="marker-active-from" placeholder="era / date"/></label><label>Active to<input id="marker-active-to" placeholder="era / date"/></label><label>Layer<select id="marker-layer"><option value="">Base map</option>${layers.map(l=>`<option value="${esc(l.id)}">${esc(l.title)}</option>`).join('')}</select></label><label>Custom image<select id="marker-custom-media"><option value="">None</option>${state.media.filter(m=>m.id!==version.mediaId).map(m=>`<option value="${esc(m.id)}">${esc(m.title||m.name)}</option>`).join('')}</select></label><label>Faction / polity<select id="marker-faction"><option value="">None</option>${factions.map(f=>`<option value="${esc(f.id)}">${esc(f.name)}</option>`).join('')}</select></label><label>Books<select id="marker-books" multiple size="3">${books.map(b=>`<option value="${esc(b.id)}">${esc(b.name)}</option>`).join('')}</select></label><label>Story relevance<input id="marker-relevance" placeholder="major, background, foreshadowing…"/></label><label class="checkbox-inline"><input id="marker-active" type="checkbox" checked/> Active marker</label></div><div class="muted small map-help map-help-row" id="marker-help">Pins can drill into detailed maps or open their lore page. Drag an existing marker to reposition it. Zoom range: 25%–300%.</div>
      <div class="map-filter-row"><input id="map-marker-search" type="search" placeholder="Search this map…"/><select id="map-marker-category-filter"><option value="">All marker categories</option>${categoryOptions.map(c=>`<option>${c}</option>`).join('')}</select><select id="map-faction-filter"><option value="">All factions</option>${factions.map(f=>`<option value="${esc(f.id)}">${esc(f.name)}</option>`).join('')}</select><select id="map-book-filter"><option value="">All books</option>${books.map(b=>`<option value="${esc(b.id)}">${esc(b.name)}</option>`).join('')}</select><select id="map-active-filter"><option value="">Active & inactive</option><option value="true">Active</option><option value="false">Inactive</option></select><input id="map-era-filter" placeholder="Era / date / tag / relevance…"/><button class="button ghost" id="clear-map-filters" type="button">Clear</button></div>
      ${layers.length?`<div class="map-layer-controls"><strong class="small">Layers</strong>${layers.map(l=>`<label><input type="checkbox" data-layer-toggle="${esc(l.id)}" ${l.data?.visible===false?'':'checked'}/> ${esc(l.title)} <span class="muted">${Math.round(Number(l.data?.opacity??.55)*100)}%</span></label><button class="tiny-x" data-delete-workspace="${esc(l.id)}" aria-label="Delete layer">×</button>`).join('')}</div>`:''}
      <div class="map-stage" id="map-stage"><div class="map-canvas" id="map-canvas" data-version-id="${esc(version.id)}" style="width:${state.mapZoom}%"><img class="map-base-image" src="${mediaUrl(media)}" alt="${esc(selected.name)} map" />${layerHtml}<svg class="map-route-overlay" viewBox="0 0 100 100" preserveAspectRatio="none">${routeHtml}</svg>${markerHtml}</div></div>
      <div class="grid two section"><section><div class="section-title"><h3>Locations on this map</h3><span class="muted small">${markers.length}</span></div><div id="map-marker-list">${markers.length?markers.map(m=>{const loc=entityById(m.locationId),drill=preferredMapForLocation(m.locationId,selected.id);return `<div class="tracking-row" data-marker-list-id="${esc(m.id)}" data-marker-list-name="${esc((m.label||loc?.name||'').toLowerCase())}" data-marker-list-category="${esc(m.category||'Other')}" data-marker-list-tags="${esc((m.tags||[]).join(' ').toLowerCase())}" data-marker-list-active="${esc(`${m.activeFrom||''} ${m.activeTo||''}`.toLowerCase())}"><div><div>${entityLink(loc,'geography')}</div><div class="muted small">${esc(m.category||'Other')} • ${Number(m.x).toFixed(1)}%, ${Number(m.y).toFixed(1)}%${drill?` • detailed map: ${esc(drill.name)}`:''}</div></div><div class="actions">${drill?`<button class="button ghost" data-open-map="${esc(drill.id)}">Open map</button>`:''}<button class="icon-btn" data-delete-marker="${esc(m.id)}" aria-label="Remove marker">×</button></div></div>`;}).join(''):'<div class="muted small">No locations pinned yet.</div>'}</div></section>
      <section><div class="section-title"><h3>Map layers & journeys</h3><span class="muted small">Derived from this map version</span></div><form id="map-layer-form" class="form-grid"><label>Name<input id="map-layer-name" required placeholder="Political borders"/></label><label>Image<select id="map-layer-media"><option value="">Choose media…</option>${state.media.filter(m=>m.id!==version.mediaId).map(m=>`<option value="${esc(m.id)}">${esc(m.title||m.name)}</option>`).join('')}</select></label><label>Opacity<input id="map-layer-opacity" type="number" min="0" max="100" value="55"/></label><div><button class="button" type="submit">Add layer</button></div></form><form id="map-route-form" class="form-grid form-section"><label>Character<select id="map-route-character"><option value="">Choose…</option>${characters.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select></label><label>Book<select id="map-route-book"><option value="">Any / none</option>${books.map(b=>`<option value="${esc(b.id)}">${esc(b.name)}</option>`).join('')}</select></label><label class="full">Route markers <span class="muted small">select in travel order</span><select id="map-route-markers" multiple size="${Math.min(7,Math.max(3,markers.length))}">${markers.map(m=>`<option value="${esc(m.id)}">${esc(m.label||entityById(m.locationId)?.name||'Location')}</option>`).join('')}</select></label><div class="full"><button class="button" type="submit">Create journey route</button></div></form>${routes.length?`<div class="tracking-list form-section">${routes.map(r=>`<div class="tracking-row"><div><strong>${esc(r.title)}</strong><div class="muted small">${(r.data?.markerIds||[]).length} stops${r.data?.bookId?` • ${esc(entityById(r.data.bookId)?.name||'Book')}`:''}</div></div><button class="tiny-x" data-delete-workspace="${esc(r.id)}">×</button></div>`).join('')}</div>`:''}</section></div>`:emptyState('Upload the visual map','This map record has no image yet. Upload a world map, regional map, city plan, political map, or any other image you want to navigate.',`<button class="button primary" data-add-map-version="${esc(selected.id)}">Upload map image</button>`)}
      ${childMaps.length?`<section class="detail-section"><div class="section-title"><div><h3>Detailed maps inside this map</h3><div class="muted small">Click through to a continent, kingdom, city, or other sub-map.</div></div></div><div class="atlas-grid">${childMaps.map(m=>atlasMapItem(m,'')).join('')}</div></section>`:''}`:emptyState('Start your atlas','Create a Map entry. Set its Geographic Scope to your world, continent, kingdom, city, or other Location, then upload the visual image.')}</section></div>`;

  document.querySelectorAll('[data-cluster-zoom]').forEach(el=>el.addEventListener('click',()=>{state.mapZoom=Math.min(300,state.mapZoom+50);renderMaps(selected.id);}));
  const applyFilters=()=>{const q=($('#map-marker-search')?.value||'').trim().toLowerCase(),category=$('#map-marker-category-filter')?.value||'',faction=$('#map-faction-filter')?.value||'',book=$('#map-book-filter')?.value||'',enabled=$('#map-active-filter')?.value||'',era=($('#map-era-filter')?.value||'').trim().toLowerCase(); document.querySelectorAll('[data-marker-id]').forEach(el=>{const layerOk=!el.dataset.markerLayer||visibleLayers.has(el.dataset.markerLayer),matches=(!q||`${el.dataset.markerName} ${el.dataset.markerTags} ${el.dataset.markerRelevance}`.includes(q))&&(!category||el.dataset.markerCategory===category)&&(!faction||el.dataset.markerFaction===faction)&&(!book||el.dataset.markerBooks.split(' ').includes(book))&&(!enabled||el.dataset.markerEnabled===enabled)&&(!era||`${el.dataset.markerTags} ${el.dataset.markerActive} ${el.dataset.markerRelevance}`.includes(era))&&layerOk;el.classList.toggle('filtered-out',!matches);}); document.querySelectorAll('[data-marker-list-id]').forEach(el=>{const marker=state.mapMarkers.find(m=>m.id===el.dataset.markerListId),matches=(!q||`${el.dataset.markerListName} ${el.dataset.markerListTags} ${marker?.storyRelevance||''}`.toLowerCase().includes(q))&&(!category||el.dataset.markerListCategory===category)&&(!faction||marker?.factionId===faction)&&(!book||(marker?.bookIds||[]).includes(book))&&(!enabled||String(marker?.active!==false)===enabled)&&(!era||`${el.dataset.markerListTags} ${el.dataset.markerListActive} ${marker?.storyRelevance||''}`.toLowerCase().includes(era));el.classList.toggle('filtered-out',!matches);});};
  ['#map-marker-search','#map-marker-category-filter','#map-faction-filter','#map-book-filter','#map-active-filter','#map-era-filter'].forEach(sel=>document.querySelector(sel)?.addEventListener('input',applyFilters)); $('#clear-map-filters')?.addEventListener('click',()=>{for(const sel of ['#map-marker-search','#map-marker-category-filter','#map-faction-filter','#map-book-filter','#map-active-filter','#map-era-filter'])if($(sel))$(sel).value='';applyFilters();});
  document.querySelectorAll('[data-layer-toggle]').forEach(input=>input.addEventListener('change',async()=>{const layer=state.workspace.find(w=>w.id===input.dataset.layerToggle);if(!layer)return; if(input.checked)visibleLayers.add(layer.id);else visibleLayers.delete(layer.id);document.querySelector(`[data-map-layer-image="${CSS.escape(layer.id)}"]`)?.classList.toggle('hidden',!input.checked);applyFilters();await putOne('workspace',{...layer,data:{...layer.data,visible:input.checked},updatedAt:now()});}));
  $('#arm-marker')?.addEventListener('click',()=>{ const locationId=$('#marker-location').value; if(!locationId) return toast('Choose a location first.'); state.markerPlacementLocationId=locationId; $('#marker-help').textContent='Pin placement armed — click the map image.'; });
  $('#map-layer-form')?.addEventListener('submit',async event=>{event.preventDefault();const mediaId=$('#map-layer-media').value;if(!mediaId)return toast('Choose a media image for the layer.');await putOne('workspace',{id:id(),kind:'mapLayer',title:$('#map-layer-name').value.trim(),data:{mapVersionId:version.id,mediaId,opacity:Math.max(0,Math.min(100,Number($('#map-layer-opacity').value)||55))/100,visible:true},createdAt:now(),updatedAt:now()});await refreshState();renderMaps(selected.id);toast('Map layer added.');});
  $('#map-route-form')?.addEventListener('submit',async event=>{event.preventDefault();const characterId=$('#map-route-character').value,markerIds=[...$('#map-route-markers').selectedOptions].map(o=>o.value);if(!characterId||markerIds.length<2)return toast('Choose a character and at least two route markers.');const character=entityById(characterId);await putOne('workspace',{id:id(),kind:'mapRoute',title:`${character?.name||'Character'} journey`,data:{mapVersionId:version.id,characterId,bookId:$('#map-route-book').value||null,markerIds},createdAt:now(),updatedAt:now()});await refreshState();renderMaps(selected.id);toast('Journey route added.');});
  let draggedMarkerId=null,dragging=false;
  document.querySelectorAll('[data-marker-id]').forEach(markerEl=>{markerEl.addEventListener('dragstart',e=>{draggedMarkerId=markerEl.dataset.markerId;dragging=true;e.dataTransfer.setData('text/plain',draggedMarkerId);});markerEl.addEventListener('dragend',()=>setTimeout(()=>dragging=false,0));markerEl.addEventListener('click',e=>{if(dragging){e.preventDefault();e.stopPropagation();}});});
  $('#map-canvas')?.addEventListener('dragover',e=>{if(draggedMarkerId)e.preventDefault();});
  $('#map-canvas')?.addEventListener('drop',async event=>{if(!draggedMarkerId)return;event.preventDefault();const marker=state.mapMarkers.find(m=>m.id===draggedMarkerId);draggedMarkerId=null;if(!marker)return;const rect=event.currentTarget.getBoundingClientRect(),x=((event.clientX-rect.left)/rect.width)*100,y=((event.clientY-rect.top)/rect.height)*100;await putOne('mapMarkers',{...marker,x:Math.max(0,Math.min(100,x)),y:Math.max(0,Math.min(100,y)),updatedAt:now()});await refreshState();renderMaps(selected.id);toast('Marker moved.');});
  $('#map-canvas')?.addEventListener('click',async event=>{ if(!state.markerPlacementLocationId||event.target.closest('.map-marker,.map-marker-cluster')) return; const rect=event.currentTarget.getBoundingClientRect(); const x=((event.clientX-rect.left)/rect.width)*100,y=((event.clientY-rect.top)/rect.height)*100; await putOne('mapMarkers',{id:id(),mapVersionId:event.currentTarget.dataset.versionId,locationId:state.markerPlacementLocationId,x:Math.max(0,Math.min(100,x)),y:Math.max(0,Math.min(100,y)),label:$('#marker-label')?.value.trim()||'',category:$('#marker-category')?.value||'Other',icon:$('#marker-icon')?.value.trim()||'',customMediaId:$('#marker-custom-media')?.value||null,tags:($('#marker-tags')?.value||'').split(',').map(t=>t.trim()).filter(Boolean),activeFrom:$('#marker-active-from')?.value.trim()||'',activeTo:$('#marker-active-to')?.value.trim()||'',layerId:$('#marker-layer')?.value||null,factionId:$('#marker-faction')?.value||null,bookIds:[...($('#marker-books')?.selectedOptions||[])].map(o=>o.value),storyRelevance:$('#marker-relevance')?.value.trim()||'',active:$('#marker-active')?.checked!==false,createdAt:now(),updatedAt:now()}); state.markerPlacementLocationId=null; await refreshState(); renderMaps(selected.id); toast('Map pin added.'); });
}

function renderMedia(){
  main.innerHTML=pageHeader('Media','A reusable private media library for maps, sketches, symbols, creatures, architecture, family trees, and other reference images.','<button class="button primary" data-upload-media="">+ Add media</button>')+`<section class="card"><div class="filter-row"><input id="media-search" type="search" placeholder="Search media titles, filenames, or tags…" /></div><div id="media-results"></div></section>`;
  const update=()=>{ const q=($('#media-search')?.value||'').trim().toLowerCase(); const items=state.media.filter(item=>!q||[item.title,item.name,...(item.tags||[])].join(' ').toLowerCase().includes(q)); $('#media-results').innerHTML=items.length?`<div class="media-grid">${items.map(item=>{const mapUse=state.mapVersions.filter(v=>v.mediaId===item.id);const src=mediaUrl(item);return `<article class="media-card">${src?`<img src="${src}" alt="${esc(item.title||item.name)}" />`:''}<div class="media-card-body"><strong>${esc(item.title||item.name)}</strong><div class="muted small">${(item.tags||[]).map(t=>`#${esc(t)}`).join(' ')||'No tags'}</div><div class="muted small">Linked to ${(item.entityIds||[]).length} entr${(item.entityIds||[]).length===1?'y':'ies'}${mapUse.length?` • used by ${mapUse.length} map version${mapUse.length===1?'':'s'}`:''}</div>${mapUse.length?'<div class="muted small" style="margin-top:8px">Delete the map version first to remove this image safely.</div>':`<button class="button danger ghost" data-delete-media="${esc(item.id)}" style="margin-top:8px">Remove</button>`}</div></article>`;}).join('')}</div>`:emptyState('No media matches',state.media.length?'Try a different search.':'Images are stored in the private R2 media library and can be linked to multiple entries without duplicate uploads.'); };
  $('#media-search').addEventListener('input',update); update();
}

function revealStoryPath(reveal){ const ref=reveal.sceneId||reveal.chapterId||reveal.bookId; return ref?storyPath(entityById(ref),state.entities):''; }
function renderReveals(){
  const mysteries=activeEntities().filter(e=>e.type==='mystery'); const foreshadow=activeEntities().filter(e=>e.type==='foreshadowing');
  const rows=[...state.clues.flatMap(c=>[c.mysteryId,...(c.mysteryIds||[])].filter(Boolean).map(mysteryId=>({kind:c.kind||'Clue',title:c.label||'Clue',storyId:c.storyEntityId,summary:c.description,mysteryId,visibility:c.visibility}))),...state.reveals.map(r=>({kind:'Reveal',title:r.title,storyId:r.sceneId||r.chapterId||r.bookId,summary:r.summary,mysteryId:r.mysteryId})),...foreshadow.map(f=>({kind:'Foreshadowing',title:f.name,storyId:f.fields?.storyEntityId,summary:f.fields?.event,mysteryId:null,visibility:f.fields?.visibility}))].sort((a,b)=>compareStoryRefs(a.storyId,b.storyId,state.entities));
  main.innerHTML=pageHeader('Reveal & Foreshadowing Board','A chronological reread view of clues, red herrings, foreshadowing, and actual reveals.','<button class="button primary" data-add-reveal="">+ Reader reveal</button>')+`<section class="card"><div class="filter-row"><select id="reveal-mystery"><option value="">All mysteries</option>${mysteries.map(m=>`<option value="${esc(m.id)}">${esc(m.name)}</option>`).join('')}</select><select id="reveal-kind"><option value="">All kinds</option>${['Clue','Red herring','Contradiction','Evidence','Foreshadowing','Reveal'].map(x=>`<option>${x}</option>`).join('')}</select></div><div id="reveal-results" class="reveal-board"></div></section>`;
  const update=()=>{ const mysteryId=$('#reveal-mystery').value,kind=$('#reveal-kind').value; const filtered=rows.filter(r=>!mysteryId||r.mysteryId===mysteryId).filter(r=>!kind||r.kind===kind); $('#reveal-results').innerHTML=filtered.length?filtered.map(r=>`<div class="reveal-node"><div class="reveal-kind">${esc(r.kind)}${r.visibility?` • ${esc(r.visibility)}`:''}</div><strong>${esc(r.title)}</strong><div class="muted small">${esc(r.storyId?storyPath(entityById(r.storyId),state.entities):'Unscheduled')}</div>${r.summary?`<div class="small">${esc(r.summary)}</div>`:''}${r.mysteryId?`<div class="small">Mystery: ${esc(entityById(r.mysteryId)?.name||'Missing')}</div>`:''}</div>`).join(''):emptyState('Nothing on this board','Add structured clues, foreshadowing entries, or reveal records.'); };
  $('#reveal-mystery').addEventListener('input',update); $('#reveal-kind').addEventListener('input',update); update();
}

function renderKnowledge(){
  const subjects=activeEntities().filter(e=>!['idea','question','trilogy','book','chapter','scene','map'].includes(e.type)).sort((a,b)=>a.name.localeCompare(b.name)); const selectedId=subjects[0]?.id||'';
  main.innerHTML=pageHeader('Character & Reader Knowledge','Track who knows the truth, who has partial information, who believes something wrong, and when that changes.','<button class="button primary" data-add-knowledge="">+ Knowledge record</button>')+`<section class="card"><div class="filter-row"><select id="knowledge-subject"><option value="">All subjects</option>${subjects.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('')}</select><select id="knowledge-state"><option value="">All states</option>${KNOWLEDGE_STATES.map(s=>`<option>${esc(s)}</option>`).join('')}</select></div><div id="knowledge-results"></div></section><section class="card section"><div class="section-title"><h2>Knowledge graph</h2><span class="muted small">Choose one subject above to visualize it.</span></div><div id="knowledge-graph">${selectedId?renderKnowledgeGraph(selectedId):'<div class="muted small">Create a knowledge record first.</div>'}</div></section>`;
  const update=()=>{ const subject=$('#knowledge-subject').value,stateFilter=$('#knowledge-state').value; const rows=state.knowledge.filter(k=>!subject||k.subjectEntityId===subject).filter(k=>!stateFilter||k.state===stateFilter); $('#knowledge-results').innerHTML=rows.length?`<div class="tracking-list">${rows.map(k=>`<div class="tracking-row"><div><div class="list-title">${esc(entityById(k.subjectEntityId)?.name||'Missing subject')} — ${esc(k.knowerKind==='reader'?'Reader':entityById(k.knowerEntityId)?.name||'Missing character')}</div><div class="list-meta">${esc(k.state)}${k.storyEntityId?` • ${esc(storyPath(entityById(k.storyEntityId),state.entities))}`:''}</div><div class="small">${esc(k.belief||'')}</div></div><button class="icon-btn" data-delete-knowledge="${esc(k.id)}">×</button></div>`).join('')}</div>`:emptyState('No knowledge records','Add a record to track a character or reader state.'); $('#knowledge-graph').innerHTML=subject?renderKnowledgeGraph(subject):'<div class="muted small">Choose one subject to visualize its knowledge states.</div>'; };
  $('#knowledge-subject').addEventListener('input',update); $('#knowledge-state').addEventListener('input',update); update();
}

function renderKnowledgeGraph(subjectId){
  const rows=state.knowledge.filter(k=>k.subjectEntityId===subjectId); if(!rows.length) return '<div class="muted small">No records for this subject.</div>'; const subject=entityById(subjectId); const w=760,h=420,cx=w/2,cy=h/2,r=150;
  const nodes=rows.map((k,i)=>({k,x:cx+Math.cos((Math.PI*2*i)/rows.length-Math.PI/2)*r,y:cy+Math.sin((Math.PI*2*i)/rows.length-Math.PI/2)*r,label:k.knowerKind==='reader'?'Reader':entityById(k.knowerEntityId)?.name||'Missing'}));
  return `<div class="graph-scroll"><svg class="graph-svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="Knowledge graph for ${esc(subject?.name||'subject')}">${nodes.map(n=>`<line x1="${cx}" y1="${cy}" x2="${n.x}" y2="${n.y}" class="graph-edge"/><text x="${(cx+n.x)/2}" y="${(cy+n.y)/2}" class="graph-edge-label">${esc(n.k.state)}</text>`).join('')}<g><circle cx="${cx}" cy="${cy}" r="48" class="graph-node-root"/><text x="${cx}" y="${cy}" class="graph-label">${esc((subject?.name||'Subject').slice(0,18))}</text></g>${nodes.map(n=>`<g><circle cx="${n.x}" cy="${n.y}" r="38" class="graph-node"/><text x="${n.x}" y="${n.y}" class="graph-label">${esc(n.label.slice(0,16))}</text></g>`).join('')}</svg></div>`;
}

function renderGraphs(){
  const entities=activeEntities().filter(e=>!['idea','question'].includes(e.type)).sort((a,b)=>a.name.localeCompare(b.name)); const chars=entities.filter(e=>e.type==='character');
  main.innerHTML=pageHeader('Relationship Graphs','Explore structured links without replacing the underlying entries. Family trees and dynasties derive from canonical blood, adoptive, guardian, sibling, and spouse relationships.','')+`<div class="grid two"><section class="card"><div class="section-title"><h2>Relationship graph</h2></div><label>Center entry<select id="graph-root"><option value="">Choose…</option>${entities.map(e=>`<option value="${esc(e.id)}">${esc(e.name)} — ${esc(typeLabel(e.type))}</option>`).join('')}</select></label><div id="relationship-graph" class="section"></div></section><section class="card"><div class="section-title"><h2>Family tree</h2></div><div class="form-grid"><label>Character<select id="family-root"><option value="">Choose…</option>${chars.map(e=>`<option value="${esc(e.id)}">${esc(e.name)}</option>`).join('')}</select></label><label>Era / house / tag filter<input id="family-filter" placeholder="optional tag or title"/></label></div><div id="family-graph" class="section"></div></section></div>`;
  $('#graph-root').addEventListener('input',e=>$('#relationship-graph').innerHTML=e.target.value?renderRelationshipGraph(e.target.value):''); const familyUpdate=()=>{const root=$('#family-root').value;$('#family-graph').innerHTML=root?renderFamilyTree(root,$('#family-filter').value):'';}; $('#family-root').addEventListener('input',familyUpdate); $('#family-filter').addEventListener('input',familyUpdate);
}

function renderRelationshipGraph(rootId){
  const net=neighborhood(rootId,state.relations,2); const ids=net.ids.filter(x=>entityById(x)); if(!ids.length) return '<div class="muted small">No links.</div>'; const w=800,h=480,pos=radialLayout(rootId,ids,w,h);
  return `<div class="graph-scroll"><svg class="graph-svg" viewBox="0 0 ${w} ${h}">${net.edges.filter(r=>pos[r.fromId]&&pos[r.toId]).map(r=>`<line x1="${pos[r.fromId].x}" y1="${pos[r.fromId].y}" x2="${pos[r.toId].x}" y2="${pos[r.toId].y}" class="graph-edge"/><text x="${(pos[r.fromId].x+pos[r.toId].x)/2}" y="${(pos[r.fromId].y+pos[r.toId].y)/2}" class="graph-edge-label">${esc(r.type.replaceAll('_',' '))}</text>`).join('')}${ids.map(nodeId=>{const p=pos[nodeId],e=entityById(nodeId);return `<g class="graph-click" tabindex="0" role="button" data-open-entry="${esc(nodeId)}" data-open-route="${esc(sectionForType(e.type))}" aria-label="Open ${esc(e.name)}"><circle cx="${p.x}" cy="${p.y}" r="${nodeId===rootId?46:34}" class="${nodeId===rootId?'graph-node-root':'graph-node'}"/><text x="${p.x}" y="${p.y}" class="graph-label">${esc(e.name.slice(0,nodeId===rootId?20:14))}</text></g>`;}).join('')}</svg></div>`;
}

function renderFamilyTree(rootId,filter=''){
  const levels=familyLevels(rootId,state.relations,3); if(levels.size<=1) return '<div class="muted small">No family links found. Add parent, child, adoptive, guardian, sibling, or spouse relationships to build the tree.</div>';
  const term=String(filter||'').trim().toLowerCase(); const visibleIds=new Set([...levels.keys()].filter(id=>{if(id===rootId||!term)return true;const e=entityById(id);return [e?.name,e?.fields?.titles,e?.fields?.homeland,...(e?.tags||[])].join(' ').toLowerCase().includes(term);})); visibleIds.add(rootId);
  const groups=[...levels.entries()].filter(([id])=>visibleIds.has(id)).reduce((acc,[id,level])=>{(acc[level]||=[]).push(id);return acc;},{}); const keys=Object.keys(groups).map(Number).sort((a,b)=>a-b); const width=900,rowH=135,height=Math.max(280,keys.length*rowH+70),positions={};
  keys.forEach((level,row)=>{const ids=groups[level]; ids.forEach((entityId,i)=>{positions[entityId]={x:width*(i+1)/(ids.length+1),y:55+row*rowH};});});
  const familyTypes=['parent_of','child_of','adoptive_parent_of','guardian_of','sibling_of','spouse_of','former_spouse_of']; const familyRels=state.relations.filter(r=>familyTypes.includes(r.type)&&positions[r.fromId]&&positions[r.toId]);
  return `<div class="graph-scroll"><svg class="graph-svg" viewBox="0 0 ${width} ${height}">${familyRels.map(r=>`<line x1="${positions[r.fromId].x}" y1="${positions[r.fromId].y}" x2="${positions[r.toId].x}" y2="${positions[r.toId].y}" class="graph-edge family-${esc(r.type)}"/><text x="${(positions[r.fromId].x+positions[r.toId].x)/2}" y="${(positions[r.fromId].y+positions[r.toId].y)/2}" class="graph-edge-label">${esc(r.type.replaceAll('_',' '))}</text>`).join('')}${Object.entries(positions).map(([entityId,p])=>{const e=entityById(entityId),sub=[e?.fields?.titles,e?.fields?.homeland].filter(Boolean).join(' • ');return `<g class="graph-click" tabindex="0" role="button" data-open-entry="${esc(entityId)}" data-open-route="characters" aria-label="Open ${esc(e?.name||'character')}"><rect x="${p.x-82}" y="${p.y-29}" width="164" height="58" rx="12" class="${entityId===rootId?'graph-family-root':'graph-family-node'}"/><text x="${p.x}" y="${p.y-5}" class="graph-label">${esc(e?.name?.slice(0,22)||'Missing')}</text>${sub?`<text x="${p.x}" y="${p.y+13}" class="graph-edge-label">${esc(sub.slice(0,28))}</text>`:''}</g>`;}).join('')}</svg></div>`;
}

function renderArchive(){
  const archived=state.entities.filter(e=>e.archivedAt).sort((a,b)=>new Date(b.archivedAt)-new Date(a.archivedAt));
  main.innerHTML=pageHeader('Archive','Archived lore is retained for history, backups, and possible reuse. Permanent deletion is available only after archiving.','')+`<section class="card"><div class="list">${archived.length?archived.map(e=>entryListItem(e,'archive')).join(''):emptyState('Archive is empty','Archiving removes entries from normal working views without destroying them.')}</div></section>`;
  if(route().selected){ const entity=entityById(route().selected); if(entity?.archivedAt) main.innerHTML+=`<section class="card section">${renderEntryDetail(entity,'archive')}</section>`; }
}

function renderSettings(){
  const project=projectSetting(); const books=activeEntities().filter(e=>e.type==='book').sort((a,b)=>(+a.fields?.order||999)-(+b.fields?.order||999));
  main.innerHTML=pageHeader('Settings & Data','Project identity, Cloudflare storage, backup/restore, and human-readable export.','')+`
    <div class="grid two"><section class="card"><h2>Project</h2><form id="project-settings" class="form-grid" style="margin-top:12px"><label class="full">Project name<input id="setting-project-name" value="${esc(project.name||'')}" /></label><label class="full">Current book<select id="setting-current-book"><option value="">None selected</option>${books.map(b=>`<option value="${esc(b.id)}" ${project.currentBookId===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label><div class="full"><button class="button primary" type="submit">Save settings</button></div></form></section><section class="card"><h2>Cloud storage</h2><p class="prose">Saved canon is stored remotely in the private Cloudflare D1 database. Maps and uploaded images are stored in the private R2 bucket. Cloudflare Access remains the login gate for the site.</p><p class="muted small">This browser only keeps temporary unsaved editor drafts. Clearing browser data can remove those drafts, but it does not erase lore already saved to D1/R2.</p><div class="section"><span class="badge ${state.storageStatus?.ready?'canon':'unknown'}">${state.storageStatus?.ready?'Connected':'Status unavailable'}</span>${state.storageStatus?.accessEmail?` <span class="muted small">${esc(state.storageStatus.accessEmail)}</span>`:''}</div></section></div>
    <section class="card section"><div class="section-title"><div><h2>Backup & restore</h2><div class="muted small">JSON is fully portable. ZIP keeps media as separate files and is better for large projects.</div></div></div><div class="actions"><button class="button" id="export-backup">Export JSON</button><button class="button primary" id="export-zip">Export ZIP backup</button><button class="button" id="import-backup">Restore JSON / ZIP</button><button class="button" id="export-markdown">Export Markdown</button></div><p class="muted small">Restore remains replace-only to avoid ambiguous merges. Export a safety backup before restoring another file.</p></section>
    ${state.legacyAvailable?`<section class="card section"><div class="section-title"><div><h2>V1 browser migration</h2><div class="muted small">A legacy V1 IndexedDB database was found on this hostname.</div></div></div><p class="prose">Import the old browser database directly into D1/R2. The legacy database is read-only during migration and is not deleted afterward.</p><button class="button primary" id="import-legacy-db">Import V1 browser database</button></section>`:''}
    <section class="card section"><h2>Database summary</h2><div class="grid stats" style="margin-top:12px"><div><div class="muted small">Entries</div><strong>${state.entities.length}</strong></div><div><div class="muted small">Relationships</div><strong>${state.relations.length}</strong></div><div><div class="muted small">Media</div><strong>${state.media.length}</strong></div><div><div class="muted small">App version</div><strong>${APP_VERSION}</strong></div></div><div class="grid stats section"><div><div class="muted small">Clues</div><strong>${state.clues.length}</strong></div><div><div class="muted small">Reveals</div><strong>${state.reveals.length}</strong></div><div><div class="muted small">Knowledge records</div><strong>${state.knowledge.length}</strong></div><div><div class="muted small">Map markers</div><strong>${state.mapMarkers.length}</strong></div></div></section>`;
}


